#!/usr/bin/env node
/**
 * Generates the sign catalogue:
 *   - one Markdown ficha per sign in `content/senales/`
 *   - a schematic SVG in `public/senales/` only when no real image was fetched
 *
 * Two sources feed it:
 *   1. `data/catalogo-oficial.json` — every code, name and official definition
 *      extracted from the BOE catalogue (RD 465/2025). Generated by
 *      `scripts/extract-catalog.mjs`.
 *   2. `data/senales.txt` — the curated layer. Optional rows that add the
 *      action, the exam mistake, related signs and a reviewed explanation for
 *      the signs that matter most (tier A).
 *
 * `data/creditos.json` (written by `scripts/fetch-sign-images.mjs`) provides the
 * attribution of the downloaded SVGs.
 *
 * Usage:
 *   node scripts/generate-signs.mjs           write files
 *   node scripts/generate-signs.mjs --check   fail if the output drifted
 */

import fs from "node:fs";
import path from "node:path";

const ROOT = process.cwd();
const CATALOG_FILE = path.join(ROOT, "data", "catalogo-oficial.json");
const CURATED_FILE = path.join(ROOT, "data", "senales.txt");
const CREDITS_FILE = path.join(ROOT, "data", "creditos.json");
const MD_DIR = path.join(ROOT, "content", "senales");
const SVG_DIR = path.join(ROOT, "public", "senales");
const CHECK = process.argv.includes("--check");
const UPDATED = "2026-11-11";
const OFFICIAL_SOURCE = "RD 465/2025, catálogo de señales verticales de circulación (Tomo I)";

const RED = "#c8102e";
const BLUE = "#0055a4";
const YELLOW = "#f2c200";
const BLACK = "#111111";
const WHITE = "#ffffff";

/* -------------------------------------------------------------- fallback art */

const GLYPHS = {
  "p-cruce": (ink) =>
    `<rect x="40" y="6" width="20" height="88" fill="${ink}"/><rect x="6" y="40" width="88" height="20" fill="${ink}"/>`,
  "p-obras": (ink) =>
    `<circle cx="44" cy="18" r="9" fill="${ink}"/><rect x="38" y="30" width="12" height="34" rx="6" fill="${ink}"/>` +
    `<rect x="22" y="64" width="56" height="8" rx="4" fill="${ink}"/><rect x="66" y="20" width="7" height="48" rx="3.5" transform="rotate(18 69 44)" fill="${ink}"/>`,
  "r-stop": (ink) =>
    `<text x="50" y="62" text-anchor="middle" font-family="system-ui, sans-serif" font-size="30" font-weight="700" fill="${ink}">STOP</text>`,
  "r-entrada-prohibida": (ink) => `<rect x="18" y="43" width="64" height="14" rx="4" fill="${ink}"/>`,
  "r-entrada-motor": (ink) =>
    `<path d="M20 62 q4 -14 14 -16 l10 -10 h12 l10 10 q10 2 14 16 l0 6 h-60 z" fill="${ink}"/>` +
    `<circle cx="30" cy="70" r="6" fill="${ink}"/><circle cx="70" cy="70" r="6" fill="${ink}"/>`,
  "r-entrada-bici": (ink) =>
    `<circle cx="28" cy="64" r="14" fill="none" stroke="${ink}" stroke-width="6"/>` +
    `<circle cx="72" cy="64" r="14" fill="none" stroke="${ink}" stroke-width="6"/>` +
    `<path d="M28 64 L46 40 L62 40 L72 64 M46 40 L56 64" fill="none" stroke="${ink}" stroke-width="6" stroke-linecap="round"/>`,
  "s-autopista": (ink) =>
    `<rect x="14" y="52" width="72" height="10" rx="3" fill="${ink}"/><rect x="26" y="20" width="10" height="44" fill="${ink}"/>` +
    `<rect x="64" y="20" width="10" height="44" fill="${ink}"/><rect x="26" y="20" width="48" height="10" rx="4" fill="${ink}"/>`,
  "s-autovia": (ink) =>
    `<rect x="14" y="52" width="72" height="10" rx="3" fill="${ink}"/><rect x="40" y="18" width="20" height="34" rx="4" fill="${ink}"/>`,
  "s-aparcamiento": (ink) =>
    `<text x="50" y="76" text-anchor="middle" font-family="system-ui, sans-serif" font-size="76" font-weight="700" fill="${ink}">P</text>`,
};

const SHAPE_TRANSFORM = {
  triangulo: "translate(22, 40) scale(0.5)",
  "triangulo-invertido": "translate(26, 18) scale(0.42)",
  octogono: "translate(0,0)",
  circulo: "translate(20, 20) scale(0.6)",
  cuadrado: "translate(22, 22) scale(0.56)",
  rectangulo: "translate(22, 34) scale(0.5)",
  rombo: "translate(0,0)",
  panel: "translate(20, 20) scale(0.6)",
};

/** Shape and colours are derived from the code range, which the BOE fixes. */
function appearance(signal) {
  const { code, family, shape, colors } = signal;

  // A curated row may override the shape; only trust it when it also brings
  // colours, otherwise derive both from the code range.
  if (shape && Array.isArray(colors) && colors.length > 0) return { shape, colors };

  if (family === "peligro") return { shape: "triangulo", colors: ["blanco", "rojo", "negro"] };
  if (code === "R-1") return { shape: "triangulo-invertido", colors: ["blanco", "rojo"] };
  if (code === "R-2") return { shape: "octogono", colors: ["rojo", "blanco"] };
  if (code === "R-3" || code === "R-4") return { shape: "rombo", colors: ["blanco", "amarillo", "negro"] };

  const numeric = Number(code.split("-")[1]);
  if (Number.isFinite(numeric)) {
    if (numeric >= 400 && numeric < 500) return { shape: "circulo", colors: ["azul", "blanco"] };
    if (numeric >= 500) return { shape: "circulo", colors: ["blanco", "negro"] };
  }

  if (family === "reglamentacion") return { shape: "circulo", colors: ["blanco", "rojo", "negro"] };
  if (code === "S-7" || code === "S-8") return { shape: "rectangulo", colors: ["blanco", "negro", "rojo"] };
  return { shape: "cuadrado", colors: ["azul", "blanco"] };
}

function fallbackSvg(signal) {
  const { shape, colors } = appearance(signal);
  const parts = ['<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 100 100" width="240" height="240" role="img">'];

  if (shape === "triangulo") {
    parts.push(`<path d="M50 6 L96 90 L4 90 Z" fill="${WHITE}" stroke="${RED}" stroke-width="10" stroke-linejoin="round"/>`);
  } else if (shape === "triangulo-invertido") {
    parts.push(`<path d="M4 10 L96 10 L50 94 Z" fill="${WHITE}" stroke="${RED}" stroke-width="10" stroke-linejoin="round"/>`);
  } else if (shape === "octogono") {
    parts.push(`<path d="M31 4 H69 L96 31 V69 L69 96 H31 L4 69 V31 Z" fill="${RED}"/>`);
  } else if (shape === "rombo") {
    const fill = signal.code === "R-3" ? YELLOW : WHITE;
    parts.push(`<path d="M50 4 L96 50 L50 96 L4 50 Z" fill="${fill}" stroke="${BLACK}" stroke-width="6"/>`);
  } else if (shape === "circulo") {
    if (colors.includes("azul")) parts.push(`<circle cx="50" cy="50" r="46" fill="${BLUE}"/>`);
    else if (signal.code === "R-101") parts.push(`<circle cx="50" cy="50" r="46" fill="${RED}"/>`);
    else parts.push(`<circle cx="50" cy="50" r="45" fill="${WHITE}" stroke="${RED}" stroke-width="10"/>`);
  } else if (shape === "cuadrado") {
    parts.push(`<rect x="5" y="5" width="90" height="90" rx="4" fill="${BLUE}"/>`);
  } else if (shape === "rectangulo") {
    parts.push(`<rect x="4" y="22" width="92" height="56" rx="3" fill="${WHITE}" stroke="${RED}" stroke-width="6"/>`);
  } else {
    parts.push(`<rect x="4" y="4" width="92" height="92" rx="4" fill="${WHITE}" stroke="${BLACK}" stroke-width="5"/>`);
  }

  if (signal.glyph && GLYPHS[signal.glyph]) {
    const ink = colors.includes("azul") ? WHITE : BLACK;
    const transform = SHAPE_TRANSFORM[shape] ?? "translate(0,0)";
    parts.push(`<g transform="${transform}">${GLYPHS[signal.glyph](ink)}</g>`);
  } else {
    // No pictogram available: the code itself, sized for short codes.
    const size = signal.code.length > 6 ? 17 : 24;
    parts.push(
      `<text x="50" y="${shape === "triangulo" ? 74 : 58}" text-anchor="middle" font-family="system-ui, sans-serif" font-size="${size}" font-weight="700" fill="${colors.includes("azul") ? WHITE : BLACK}">${signal.code}</text>`,
    );
  }

  if (["R-101", "R-102", "R-108", "S-2", "S-4", "S-8"].includes(signal.code)) {
    parts.push(`<rect x="6" y="92" width="88" height="7" rx="3.5" fill="${signal.code.startsWith("S") ? BLACK : WHITE}" transform="rotate(-45 50 50)"/>`);
  }

  parts.push("</svg>");
  return parts.join("\n");
}

/* ------------------------------------------------------------------- inputs */

function readJson(file, fallback) {
  if (!fs.existsSync(file)) return fallback;
  return JSON.parse(fs.readFileSync(file, "utf8"));
}

function parseCurated() {
  if (!fs.existsSync(CURATED_FILE)) return new Map();

  const rows = new Map();
  const problems = [];

  fs.readFileSync(CURATED_FILE, "utf8")
    .split("\n")
    .forEach((line, index) => {
      const trimmed = line.trim();
      if (trimmed.length === 0 || trimmed.startsWith("#")) return;

      const fields = trimmed.split("|");
      if (fields.length !== 14) {
        problems.push(`data/senales.txt line ${index + 1}: expected 14 fields, found ${fields.length}`);
        return;
      }

      const [code, name, family, subfamily, shape, colors, glyph, meaning, action, where, mistake, related, tier, verified] =
        fields.map((field) => field.trim());

      rows.set(code, {
        code,
        name,
        family,
        subfamily,
        shape: shape || null,
        colors: colors ? colors.split(",").map((color) => color.trim()).filter(Boolean) : null,
        glyph: glyph || null,
        meaning,
        action: action || null,
        where: where || null,
        mistake: mistake || null,
        related: related ? related.split(",").map((value) => value.trim()).filter(Boolean) : [],
        tier: tier || "A",
        verified: verified === "true",
      });
    });

  if (problems.length > 0) {
    console.error(problems.join("\n"));
    process.exit(1);
  }

  return rows;
}

/* ---------------------------------------------------------------- rendering */

function yamlList(values) {
  return values.length === 0 ? "[]" : `\n${values.map((value) => `  - "${value}"`).join("\n")}`;
}

function quote(value) {
  return value.replace(/\\/g, "\\\\").replace(/"/g, '\\"');
}

function renderFicha(signal) {
  const lines = [
    "---",
    `code: "${signal.code}"`,
    `name: "${quote(signal.name)}"`,
    `family: "${signal.family}"`,
    `subfamily: "${signal.subfamily}"`,
    `shape: "${signal.shape}"`,
    `colors:${yamlList(signal.colors)}`,
    `meaning: "${quote(signal.meaning)}"`,
  ];

  if (signal.action) lines.push(`action: "${quote(signal.action)}"`);
  if (signal.where) lines.push(`where: "${quote(signal.where)}"`);
  if (signal.mistake) lines.push(`mistake: "${quote(signal.mistake)}"`);

  lines.push(
    `related: ${signal.related.length === 0 ? "[]" : `[${signal.related.map((code) => `"${code}"`).join(", ")}]`}`,
    `image: "/senales/${signal.slug}.svg"`,
    `imageAlt: "${quote(`${signal.code}, ${signal.name}`)}"`,
    `imageCredit: "${quote(signal.imageCredit)}"`,
    `officialSource: "${quote(OFFICIAL_SOURCE)}"`,
    `tier: "${signal.tier}"`,
    "isNew: false",
    `verified: ${signal.verified}`,
    `updated: ${UPDATED}`,
    "---",
    "",
  );

  const body = [];
  if (signal.extraParagraphs.length > 0) {
    body.push("## Definición oficial del catálogo", "", ...interleave(signal.extraParagraphs));
  }

  return `${lines.join("\n")}\n${body.length > 0 ? `${body.join("\n")}\n` : ""}`;
}

function interleave(paragraphs) {
  const output = [];
  paragraphs.forEach((paragraph, index) => {
    if (index > 0) output.push("");
    output.push(paragraph);
  });
  return output;
}

/* -------------------------------------------------------------------- main */

const official = readJson(CATALOG_FILE, null);
if (!official) {
  console.error(`Missing ${path.relative(ROOT, CATALOG_FILE)}. Run scripts/extract-catalog.mjs first.`);
  process.exit(1);
}

const curated = parseCurated();
const credits = readJson(CREDITS_FILE, {});

const signals = official.map((entry) => {
  const override = curated.get(entry.code);
  const look = appearance({
    ...entry,
    ...(override?.shape ? { shape: override.shape, colors: override.colors } : {}),
  });
  const slug = entry.code.toLowerCase();
  const credit = credits[entry.code];
  const realImage = fs.existsSync(path.join(SVG_DIR, `${slug}.svg`));

  const paragraphs = Array.isArray(entry.paragraphs) ? entry.paragraphs : [entry.definition].filter(Boolean);
  const meaning = override?.meaning ?? entry.definition ?? entry.name;

  return {
    ...entry,
    ...(override ?? {}),
    slug,
    // The name always comes from the BOE catalogue; the curated row only adds
    // study notes.
    name: entry.name,
    family: override?.family ?? entry.family,
    subfamily: override?.subfamily ?? entry.subfamily,
    shape: look.shape,
    colors: look.colors,
    meaning,
    action: override?.action ?? null,
    where: override?.where ?? null,
    mistake: override?.mistake ?? null,
    related: override?.related ?? [],
    tier: override?.tier ?? "B",
    verified: true,
    imageCredit: credit
      ? [credit.artist, credit.license].filter(Boolean).join(" · ")
      : "Pictograma esquemático propio; no reproduce el símbolo oficial",
    extraParagraphs: override ? [] : paragraphs.slice(1),
    needsGeneratedArt: !realImage,
  };
});

const known = new Set(signals.map((signal) => signal.code));
for (const code of curated.keys()) {
  if (!known.has(code)) console.warn(`  ! data/senales.txt row ${code} has no match in the official catalogue`);
}
for (const signal of signals) {
  for (const code of signal.related) {
    if (!known.has(code)) console.warn(`  ! ${signal.code} links to ${code}, which is not in the catalogue`);
  }
}

if (!CHECK) {
  fs.mkdirSync(MD_DIR, { recursive: true });
  fs.mkdirSync(SVG_DIR, { recursive: true });
}

const drift = [];
let generatedArt = 0;

for (const signal of signals) {
  const mdPath = path.join(MD_DIR, `${signal.slug}.md`);
  const svgPath = path.join(SVG_DIR, `${signal.slug}.svg`);
  const md = renderFicha(signal);

  if (CHECK) {
    const current = fs.existsSync(mdPath) ? fs.readFileSync(mdPath, "utf8") : null;
    if (current !== md) drift.push(path.relative(ROOT, mdPath));
    continue;
  }

  fs.writeFileSync(mdPath, md);

  if (signal.needsGeneratedArt) {
    fs.writeFileSync(svgPath, fallbackSvg(signal));
    generatedArt += 1;
  }
}

if (CHECK && drift.length > 0) {
  console.error("Generated fichas are out of date. Run `npm run generate:signs`:");
  for (const file of drift.slice(0, 20)) console.error(`  · ${file}`);
  console.error(`  (${drift.length} files)`);
  process.exit(1);
}

const withRealImage = signals.filter((signal) => Boolean(credits[signal.code])).length;
console.log(
  `${CHECK ? "Checked" : "Generated"} ${signals.length} fichas · ${withRealImage} con imagen de Commons · ${signals.length - withRealImage} con pictograma propio`,
);
if (!CHECK) console.log(`  tier A: ${signals.filter((signal) => signal.tier === "A").length} · SVG esquemáticos escritos: ${generatedArt}`);
